const inputData = $input.item.json;
let rawText = inputData.text || inputData.output || (typeof inputData === 'string' ? inputData : JSON.stringify(inputData));
const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();

let g = null;
try { g = JSON.parse(cleaned); } catch (e) { g = null; }

let src = {};
try { src = $('Loop Over Items').item.json; } catch (err) { src = {}; }

// Pass Claude/seed fields straight through, untouched.
const pass = {
  idea_id: src.idea_id || "",
  category_id: src.category_id || "",
  category_name: src.category_name || "",
  category_slug: src.category_slug || "",
  subcategory_id: src.subcategory_id || "",
  subcategory_name: src.subcategory_name || "",
  subcategory_slug: src.subcategory_slug || "",
  focus_keyword: src.focus_keyword || "",
  additional_keyword_1: src.additional_keyword_1 || "",
  additional_keyword_2: src.additional_keyword_2 || "",
  business_description: src.business_description || "",
  collection_id: src.collection_id || "",
  title: src.title || "",
  slug: src.slug || "",
  seo_title: src.seo_title || "",
  meta_description: src.meta_description || "",
  tags: src.tags || "[]",
  external_links: src.external_links || "[]",
  internal_link_anchors: src.internal_link_anchors || "[]",
  research_facts: src.research_facts || "{}"
};

const str = (v) => (v === undefined || v === null) ? "" : String(v);
// The sheet needs text; Supabase jsonb needs a real array. Emit both.
// Writing the stringified form into a jsonb column is what double-encoded
// all 290 existing rows -- jsonb_typeof returns "string", not "array".
const arr = (v) => Array.isArray(v) ? JSON.stringify(v) : (typeof v === 'string' ? v : JSON.stringify(v || []));
const real = (v) => {
  if (Array.isArray(v)) return v;
  if (typeof v === 'string') { try { const p = JSON.parse(v); return Array.isArray(p) ? p : []; } catch (e) { return []; } }
  return [];
};
const realObj = (v) => {
  if (v && typeof v === 'object' && !Array.isArray(v)) return v;
  if (typeof v === 'string') { try { const p = JSON.parse(v); return (p && typeof p === 'object') ? p : {}; } catch (e) { return {}; } }
  return {};
};

// If Gemini failed, mark for retry but KEEP all of Claude's work intact.
if (!g || !g.summary) {
  return { json: { ...pass, status: "needs_retry",
    tags_json: real(pass.tags), external_links_json: real(pass.external_links),
    internal_link_anchors_json: real(pass.internal_link_anchors),
    research_facts_json: realObj(pass.research_facts) } };
}

const trend = parseInt(g.trend_score, 10) || 70;
const tier = g.tier || (trend >= 88 ? "premium" : "free");

return {
  json: {
    ...pass,
    summary: str(g.summary),
    market_opportunity: str(g.market_opportunity),
    target_customer: str(g.target_customer),
    how_you_make_money: str(g.how_you_make_money),
    startup_cost: str(g.startup_cost),
    income_potential: str(g.income_potential),
    competition_edge: str(g.competition_edge),
    getting_started_steps: arr(g.getting_started_steps),
    tools_needed: arr(g.tools_needed),
    time_to_first_customer: str(g.time_to_first_customer),
    faq_json: arr(g.faq_json),
    pros_json: arr(g.pros_json),
    cons_json: arr(g.cons_json),
    verdict: str(g.verdict),
    trend_score: trend,
    tier: tier,
    status: "completed",
    // Real arrays/objects for the jsonb columns in Supabase.
    tags_json: real(pass.tags),
    external_links_json: real(pass.external_links),
    internal_link_anchors_json: real(pass.internal_link_anchors),
    research_facts_json: realObj(pass.research_facts),
    getting_started_steps_json: real(g.getting_started_steps),
    tools_needed_json: real(g.tools_needed),
    faq_json_json: real(g.faq_json),
    pros_json_json: real(g.pros_json),
    cons_json_json: real(g.cons_json)
  }
};

// Quality gate for generated idea narratives.
//
// Runs between the JSON parser and the sheet write, so nothing reaches the
// sheet or Supabase without passing. It REJECTS the unambiguous and FLAGS the
// arguable, deliberately: an over-eager guard throws away good work.
//
// That distinction was learned from real data. A crude banned-word scan over
// the 290 live rows flagged 11 problems; on reading them, only 5 were real:
//   "you unlock the lower steel cabinet"  -- a key in a lock, not marketing
//   "a seamless loop"                     -- the standard audio term
//   "seamless reweaving"                  -- literally no visible seam
//   "post-1960 premium pens"              -- a product category, not a date
// Rejecting those would have destroyed correct copy. So context-dependent
// words are flagged for review, never used to fail a row.
const CURRENT_YEAR = new Date().getFullYear();

// Words that have no legitimate use in this voice, in any context.
const HARD_BANNED = /\b(game.?changer|revolutionis|revolutioniz|in today'?s fast.?paced|dive in|look no further|synergy|paradigm|cutting.?edge|best.?in.?class|world.?class)\b/i;

// Words with real literal uses. Flagged, never fatal.
const SOFT_BANNED = /\b(unlock|seamless|leverage|empower|elevate|holistic|robust|ecosystem)\b/i;

// Naming the validation vendors is never acceptable. This has shipped as a
// live defect before and is the one rule with no exceptions.
const VENDORS = /\b(claude|perplexity|chatgpt|openai|grok|gemini|copilot|anthropic)\b/i;

const NARRATIVE = ['summary','market_opportunity','target_customer','how_you_make_money',
                   'startup_cost','income_potential','competition_edge','time_to_first_customer','verdict'];

// A failure here used to throw, which aborted the entire execution and lost
// every row still queued behind it. One bad generation is not a reason to
// discard fifty good ones. Failures are now marked needs_review and carried
// forward: the sheet records why, and the Supabase insert is skipped for
// that row only.
const out = [];

for (const item of $input.all()) {
  const j = item.json;

  // Rows the parser already marked for retry pass through untouched -- they
  // carry the researcher's work and must not be lost to a guard.
  if (j.status === 'needs_retry') { out.push(item); continue; }

  const flags = [];
  const rejects = [];

  for (const field of NARRATIVE) {
    const val = String(j[field] ?? '');
    if (!val) continue;

    if (VENDORS.test(val)) {
      rejects.push(`${field} names an AI vendor -- "${val.match(VENDORS)[0]}"`);
    }
    if (HARD_BANNED.test(val)) {
      rejects.push(`${field} uses banned filler -- "${val.match(HARD_BANNED)[0]}"`);
    }

    // A RECENT year dates the page and is fatal. An older year is usually a
    // historical reference ("post-1960 pens") and is only flagged.
    const years = [...val.matchAll(/\b(19|20)\d{2}\b/g)].map((m) => parseInt(m[0], 10));
    const recent = years.filter((y) => y >= CURRENT_YEAR - 2);
    if (recent.length) {
      rejects.push(`${field} contains ${recent[0]}, which dates the page`);
    }
    if (years.length) flags.push(`${field}: historical year ${years[0]}`);
    if (SOFT_BANNED.test(val)) flags.push(`${field}: "${val.match(SOFT_BANNED)[0]}" -- check it is literal, not marketing`);
  }

  const summaryLen = String(j.summary ?? '').length;
  if (summaryLen < 200) {
    rejects.push(`summary is only ${summaryLen} characters, too thin to publish`);
  }

  const trend = parseInt(j.trend_score, 10);
  // 55-98, the band the error message has always stated. Verified against
  // the live table before tightening: all 290 rows sit between 64 and 89, so
  // this rejects nothing real. A score outside it is a model artefact.
  if (!Number.isFinite(trend) || trend < 55 || trend > 98) {
    rejects.push(`trend_score is "${j.trend_score}", outside the honest 55-98 band`);
  }

  if (rejects.length) {
    out.push({ json: { ...j, status: 'needs_review',
      quality_flags: flags.join(' | '),
      quality_error: `${j.slug || j.idea_id}: ` + rejects.join('; ') } });
  } else {
    out.push({ json: { ...j, quality_flags: flags.join(' | ') } });
  }
}

return out;

// Runs when "Loop Over Items" finishes, on the "done" output.
//
// This branch was previously connected to nothing, which is why a starved run
// looked identical to a working one: the loop and the IF would flash once per
// row, nothing downstream would light up, and the execution would report
// success having written absolutely nothing.
//
// A run where every row is skipped is not a success. Say so out loud.
const items = $input.all();
const total = items.length;

let processed = 0;
let skipped = 0;
for (const item of items) {
  const rf = String(item.json.research_facts ?? '').trim();
  if (rf.length > 50) processed += 1; else skipped += 1;
}

const summary = {
  total_rows_read: total,
  rows_with_research_facts: processed,
  rows_skipped_missing_research_facts: skipped,
};

if (total > 0 && processed === 0) {
  summary.warning =
    `All ${total} pending rows were skipped: research_facts is empty on every one. ` +
    `The Stage 1 research pass has not run for these rows, so there is nothing for ` +
    `the writer to work from. This run wrote nothing.`;
}

return [{ json: summary }];

// Merge Stage 1 research onto the seed row from the sheet.
//
// The sheet supplies only the seed columns (category, subcategory, keywords,
// business_description). research_facts is empty on every pending row there,
// so the researcher's output -- title, slug, the SEO fields, tags, links and
// research_facts -- is read from Supabase table idea_research instead.
//
// A miss is not an error. The lookup runs with alwaysOutputData, so an idea
// with no research yet arrives as an empty object, falls through with an empty
// research_facts, and is skipped by the gate exactly as before.
const src = $('Loop Over Items').item.json;
const found = $input.item.json || {};
const hit = Boolean(found && found.idea_id);

const str = (v) => (v === undefined || v === null) ? '' : String(v);
// jsonb comes back parsed; the gate and the writer prompt both want text.
const text = (v) => (v === undefined || v === null) ? ''
  : (typeof v === 'string' ? v : JSON.stringify(v));
const pick = (k, fb) => (hit && found[k]) ? found[k] : fb;

return {
  json: {
    ...src,
    title:                 str(pick('title',            src.title)),
    slug:                  str(pick('slug',             src.slug)),
    seo_title:             str(pick('seo_title',        src.seo_title)),
    meta_description:      str(pick('meta_description', src.meta_description)),
    tags:                  text(pick('tags',                  src.tags)) || '[]',
    external_links:        text(pick('external_links',        src.external_links)) || '[]',
    internal_link_anchors: text(pick('internal_link_anchors', src.internal_link_anchors)) || '[]',
    research_facts:        text(pick('research_facts',        src.research_facts)),
    research_found:        hit,
  },
};
